INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41289, '你将获得：设计图：迷人的黄玉项链') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Alluring Citrine Choker
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41291, '湿漉漉还在滴水，但完好无损。感激之情自不必说，我的学生。那么，我们继续吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Soggy and dripping, but still intact. My gratitude is guaranteed, pupil. Well then, let us proceed.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41292, '将对你施放以下法术：大师级金匠学') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The following spell will be cast on you: Artisan Goldsmith
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41293, '你将获得：设计图：精致的金手镯') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Elaborate Golden Bracelets
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41294, '你将获得：设计图：深海之心') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Heart of the Sea
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41295, '你将获得：设计图：加莉特蕾娅之法杖') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Staff of Gallitrea
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41299, '你将获得：设计图：德莱尼水晶魔棒') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Draenethyst Baton
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41301, '我看你回来了。现在也让我们确保你能顺利离开……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- I see you have returned. Now let us ensure you will be able to leave as well...
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41302, '你将获得：设计图：精致秘银护符') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Delicate Mithril Amulet
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41303, '格里兹比？不，他没离开棘齿城，至少不是坐船走的。但他确实到过这里，这点可以肯定。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Grizzby? No, he didnt leave Ratchet, atleast not by boat. But he did make it here, thats for sure.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41305, '你将获得：设计图：精致秘银护符') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Delicate Mithril Amulet
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41306, '你是来帮可怜的萨赫希的吗？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Are you here to help poor Sahrhee?
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41309, '你将获得：设计图：华丽秘银手镯') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Ornate Mithril Bracelets
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41312, '你将获得：麦迪文的权杖头') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Sceptre Head of Medivh
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41315, '你将获得：设计图：皇家曙光权杖') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Regal Twilight Staff
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41318, '你将获得：设计图：精致钻石宝冠') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Mastercrafted Diamond Crown
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41319, '你将获得：设计图：精制钻石手镯') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Mastercrafted Diamond Bangles
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41327, '你将获得：纯净德莱尼水宝石') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Pure Draenethyst Gemstone
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41328, '你将获得：纯净德莱尼水宝石') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Pure Draenethyst Gemstone
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41329, '唉，你就只能弄到这个？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Aw, was this the best ye could get?
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41330, '这才是好东西！弟兄们都已经在舔嘴唇了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Thats the good stuff! The lads be already licking they lips.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41331, '嚯，你这是从哪儿弄来的？这玩意儿够在海盗王的餐桌上敬一杯的！要是真有那么个海盗王的话……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Oho, now whered you get that? Something yed toast at the table of the Pirate King! If there were one
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41332, '我的天老爷！这鬼东西的滋味像海妖的亲吻。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Shiver me timbers! The damned thing feels like the kiss of a Siren.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41336, '你将获得：设计图：黄金符文戒指') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Golden Runed Ring
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41342, '你将获得：白色雄鹿之雕文') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Glyph of the White Stag
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41343, '一支大得滑稽的蜡烛。你这人爱开玩笑是吧？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- A comically large candle. Are you a jokester?
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41344, '你将获得：变形术之秘典：啮齿动物') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Tome of Polymorph: Rodent
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41345, '大海轰鸣，一股恐惧的浪潮笼罩艾萨拉。有什么东西正从海中升起！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The seas rumble and a wave of dread washes over Azshara. Something emerges from the ocean!
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41346, '你将获得：古老神像下碎片') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Bottom Piece of an Ancient Idol
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41348, '<搜寻看来毫无希望，这本日志想必也不会有什么收获。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <The search seems hopeless, surely this journal will not yield anything either.>
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41351, '你将获得：镶宝的红宝石指环') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Jeweled Ruby Ring
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41354, '信不信由你，你展现出了极大的善意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Believe it or not, you have shown great kindness.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41355, '一件极珍贵的物品。这座昔日雄城最后的遗物之一。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- A most treasured item. One of the final relics of this once mighty city.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41358, '这顾虑很合理。我本无需向你解释——不过我想阿尔多雷尔不一样。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- A fair concern. I owe you no explanation – but I suppose AlDorel is different.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41360, '你可以从这些奖励中选择其一：织法者之爪击、极寒冰霜之魔棒、地脉流之碎片') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Claw of the Mageweaver Rod of Permafrost Shard of Leyflow
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41362, '你将获得：华丽山地宝石、设计图：华丽山地宝石') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Gorgeous Mountain Gemstone Plans: Gorgeous Mountain Gemstone
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41363, '你可以从这些奖励中选择其一：法力药水、强效治疗药水') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Mana Potion Greater Healing Potion
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41364, '这么说影牙城堡很快就要被攻打了。很好。既然你来了，不介意帮我个忙吧？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- So the Shadowfang Keep will soon be raided. Good. While youre here, you wouldnt mind doing me a favo
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41366, '你将获得：救赎之搜寻项链') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Necklace of Redemption
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41367, '你将获得：科卡尔披风') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Kolkar Drape
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41368, '你可以从这些奖励中选择其一：坚固的磨刀石、坚固的平衡石') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Solid Sharpening Stone Solid Weightstone
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41369, '你将获得：麦迪文之节杖魔棒') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Scepter Rod of Medivh
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41372, '你将获得：麦迪文之节杖') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: The Scepter of Medivh
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41373, '啊，《科赞食谱》，还是加斯蒂诺亲笔，你在哪找到的？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Ah, "Recipes of Kezan" by none other than Gastino, whered you find that?
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41374, '你将获得：配方：强能草药沙拉') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Recipe: Empowering Herbal Salad
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41375, '你在取笑我吗？这看上去像是小孩子写的——$B$B<莱德罗斯默默盯着空中看了片刻。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Are you mocking me? This looks like something a child wro–$B$B<Lydros stares silently into thin air 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41376, '你将获得：奥术树人之雕文') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Glyph of the Arcane Treant
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41378, '干得漂亮。现在把血交给我，我来准备所需之物。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Impressive. Now, give the blood to me. I will prepare what is needed.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41379, '纯净的狼人之血，正如乌尔所描述……是的，这非常有用。不过现在听我说，我有很多事情要告诉你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Pure worgen blood, just like Ur described... Yes, this will be very useful. But now listen, as I hav
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41380, '这么说，传说中的穆沙镰刀被找到了。大德鲁伊梦风派你来找我，很有见地。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- So, the fabled Scythe of Musha has been found. This Arch Druid Dreamwind has been wise to send you t
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41381, '一如既往的精工之作。现在，把它交给我。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Exquisite work, as always. Now, hand it to me.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41383, '现在你知道了。我们剩下的时间不多了。你必须找到它们，镰刀才能得到净化。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- So now you know. We dont have much time left. You must find them, so that the Scythe can be cleansed
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41384, '邪恶的普里科利希·怒月死了！确实了得。你救了我们所有人。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The foul pricolich Gnarlmoon is dead! Impressive indeed. You have saved us all.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41386, '邪恶的普里科利希·狼人死了！你阻止了他，为瓦琳德报了仇！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The vile pricolich Lycan is dead! You stopped him and avenged Velinde!
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41388, '值得称赞。把这几课记在心里，对你今后在这条路上的成就至关重要。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Commendable. Taking these lessons to heart is imperative for your future success on this road youve 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41389, '你将获得：决心之证词') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Testimony of Resolve
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41390, '是伦兹克派你来的？很好。我正缺些人手。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Renzik sent you? Good. I could use a bit more manpower.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41392, '你可以从这些奖励中选择其一：特工披风、正直之护腕') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Operative Cloak Cuffs of Integrity
