INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41275, '嚯，是梅瓦派你来的？那丫头好久没在这儿露过面了！她要我教你金饰加工？这倒怪不得她——毕竟我确实是全艾泽拉斯最出色的珠宝匠。$B$B那就别再等了，如何？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Oho, so Mayva sent you? That snappy gal hasnt shown her face around here in AGES! And she wants me t
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41276, '一路远行而来吧？这片土地算不上好客，却有一种原始的、未经触碰的美，别处难得一见。不过你并不是为此而来，对吧？说吧，是谁让你来找老加卡尔的？$B$B金饰加工？这是我许久不怎么施展的老手艺了。部落更用得上我的炼金本事。但若你愿意拜我为师、听我讲讲能讲的东西，那就请便吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Long travel, I take it? These lands arent the most welcoming, but they offer a primal beauty, untouc
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41278, '<瑟格伦的目光在你和你带来的水晶之间来回移动。盯着你看了好一会儿后，他点了点头。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <Thegrens gaze switches between you and the crystal you brought with you. After staring at you for a
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41280, '<与矮人无可挑剔的切工相比，你对自己那些拙劣的仿作几乎感到羞愧。可是出乎意料的是，瑟格伦脸上又浮起一丝笑意，一股成就感令你精神一振。$B$B下一步在等着你。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <Comparing them to the dwarfs flawless cuts, you feel almost embarrassed looking at feeble attempts 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41281, '<把沉重的石板呈给瑟格伦时，你感到一阵自豪——他琥珀色的眼睛因兴奋而发亮。石板的晶光在荒芜之地刺眼的烈日下反射得格外美丽，让你所有的辛劳更显值得。$B$B瑟格伦转向你，赞许地点了点头。最后一步就在眼前。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <Presenting the heavy slab of stone to Thegren brings a sensation of pride to you, as you see his am
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41290, '<那位上层精灵不屑地打量你。>$B$B先是下头那个笨手笨脚的人类，现在又轮到你？一位艺术家这辈子就不能有一次清静吗？说吧，是谁让你来找巧匠的？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <The Highborne eyes you dismissively.>$B$BFirst this bumbling human down there, and now you? Can an 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41296, '你臭得很，$R，臭气冲天。我能闻到你身上那股天真的、无谓的希望的可鄙气味。让我猜猜——是桑夫·克拉和他那帮可怜虫派你来从我伟大的头脑里套取知识吧。若真是如此，那我倒迫不及待想看你脸上失望的表情了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You reek, $R, horribly. I can smell the despicable stench of naivety and senseless hope on you. Let 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41297, '果然还是损坏了。粗野蛮徒。至少里面的东西完好无损。那你就算走运了。不过，这卷轴……难道是……？肮脏的东西，你的贪婪帮了我大忙，但你的报应还不到时候。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Damaged, as to be expected. Savage brute. Atleast its contents are intact. You can consider yourself
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41298, '<那破碎者德莱尼以出人意料的力量抓住那颗断下的头颅。他朝马托加血淋淋的面皮上啐了一口，把它摔在地上，又狠狠踩进红色的沙土里。>$B$B可悲的东西，毁灭与荒芜的使者。愿你祖先将你的灵魂撕成碎片，因为你背叛了你的族人、你的血亲！你夺走了我们——夺走了我逃离的手段——这让我从心底感到恶心。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <The broken draenei grabs the decapitated head with unexpected force. Spitting on the bloodied skin 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41300, '派个手下独自去解决自己的麻烦？没想到那个扭来扭去的小侏儒还有这一手。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Sending a goon on his own to sort out his problems? Now this is something I hadnt anticipated of tha
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41304, '<塔克纳兹读着你在那地精身上找到的契约。他越往下读，绿色的皮肤就越发涨红。>$B$B啊，那些背后捅刀、啃伤口过活的穴居人！离开风险投资公司是纳特这辈子做过最正确的事，我受够了他们那些见不得光的手段。我不仅丢了所有珍贵的珠宝，还失去了最好的承包商，要找个替代的人不知要等到何年何月！哦，格里兹比，你这老混蛋，你本该有更好的下场，好得多……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <Tacknazz reads the contract you found on the goblin. The further he reads, the redder his green ski
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41307, '这是什么？特拉西斯的货？我等这个等了好久！那地精和他那一塌糊涂的服务到底在搞什么？不管怎样，谢谢你替他完成了活。要不是他有那么独家的货源，这就是我最后一次在他那儿订货了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- What is this? Traxis delivery? Ive been waiting ages for this! Whats up with that goblin and his lac
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41308, '我可不敢称那个小东西为伙伴，但我们之间共享着许多宝贵的知识，所以我才容忍她的存在和请求。说吧，她今天又要什么？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- I dare not call that tiny being a partner, but we share much valuable knowledge between us, so I tol
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41310, '卡德加？这名字我已许久未闻，自他离开这个世界后，我以为再也不会听到。无论他在何处、是生是死——但愿他的灵魂自由而清明。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Khadgar? A name I havent heard in ages and one I thought Id never hear again following his departure
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41311, '那件握物又回到了我手里，简直像个诅咒。你居然毫发无伤地回来了，令我十分佩服——你的实力已可与大英雄比肩。$B$B现在说说那件握物……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The clutch has found its way back to me, almost like a curse. I am most impressed you returned somew
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41313, '这些看上去极不自然。地脉水晶只在罕见的情况下，当地脉精华渗过地表时才会自行凝结，可这些……它们的形成方式似乎不同，某种意义上像是被强行促成的。嗯，蹊跷……$B$B<大法师克希雷姆一边端详着水晶，一边沉思片刻。突然，他灵光一现。>$B$B$N，对此有许多说得通的解释。但要证实我自己的推论，我得先做些试验。你愿意帮我吗？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Those appear positively unnatural. Ley line crystals materialize themselves on rare occasions when f
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41314, '令人遗憾，也令人不安。今后挑选学徒，我必须更加审慎。塔蕾莎竟如此鲁莽，实在令人费解，我没想到她会做出这种举动。诚然，她的急切显而易见，但我原以为——也希望——那是出于对知识的追求，而非对力量的贪求。无论她为谁效力，我都会让他们为自己的所作所为受到清算。$B$B不过，聚焦宝珠已回到我手中，我们终于能查清这地脉之谜了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Regrettable, and concerning. I have to be even more selective in my choice of apprentices in the fut
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41317, '哎哟，这玩意儿真烫！弄到手一定费了不少劲，幸好你比它更硬气，是吧？那么，别再等了，把这宝贝撬开！$B$B<凡兹把碎片移到沉重的锁上，碎片散出灼热的气息，锁应声开裂，随即落进沙中。凡兹兴致勃勃地翻起那本书。>$B$B空的。空的。空的。空的！除了两页之外全是空的！我简直不敢信！这是什么恶劣的玩笑吗？！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Ouch, that thing is hot! Mustve been real tough to get, luckily youre on the tougher side of life, e
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41320, '如你所见，我所目睹的一切，为避难所中的同胞描绘出一幅惨淡的图景。我带领他们来到这个世界寻求安宁，如今我们的过去却再度作祟。我必须阻止这一切，可凭我一人无能为力。陌生的朋友，你愿意像帮助桑夫·克拉那样帮我一把吗？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- As you can see, what I have witnessed paints a grim picture for my brethren at the Harborage. I have
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41321, '<阿克扎多尔接过黏滑带血的大脑，一块块嚼了下去。看上去令人作呕。>$B$B唔，口感有点像海绵，倒不难吃。相信我，我吃过更糟的。谢谢你，$N，我已经能感觉到神智的虚弱在消退了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <Akh Zador takes the slimy, bloody brains and chomps them piece by piece. It is revolting to look at
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41322, '辛香带辣——这正是德莱尼菜肴的典型风味。谢谢你带来足够的食物，让我恢复了元气。你的善意弥足珍贵，我真希望能用我族人的传统菜肴回报你，一道用德拉诺食材烹制的菜。不过我扯远了，在这儿，多愁善感毫无用处。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Zesty and spicy - a combination typical for draenei cuisine. Thank you for providing me with enough 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41323, '我的手杖！上一次见它这般残破，还是多年前我们逃离德拉诺的时候。永远感谢你，$N。还有这个……你们叫它魔精？这股盘旋的能量对我来说完全陌生。你们这个世界恐怕永远都会让我困惑。$B$B<阿克扎多尔以拳捶胸，向你的事迹致敬。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- My cane! Ive only seen it this disheveled after we escaped Draenor years ago. Eternal gratitude to y
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41324, '是阿克扎多尔大人派你来的？！真是太好了！我和部族的人都担心得要命，甚至已经做了最坏的打算。失去这样一位挚友、可信的首领和精湛的裂隙行者，我们谁也承受不起。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Master Akh Zador sends you?! What a relief! Me and the tribe were worried sick, and had already fear
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41325, '一个幽影？它还提到桑夫部族和阿克扎多尔被奴役？！这消息太糟了，$R。为了我们所有人，但愿我错了——但我担心避难所正面临危险，极大的危险！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- A shadowed specter? And it spoke of the enslavement of the Sanv tribe and Akh Zador?! This is grim n
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41326, '你可以从这些奖励中选择其一：裂隙行者的法衣、虚空碎片指环、避难所守卫肩铠、德莱尼水坠饰') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Garbs of the Riftwalker Nethershard Band Harborage Defender Paul
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41338, '听到月光林地愿伸出援手，令人安心，年轻人。我们正面临的动荡应是我们所有人的事，置之不理难道不危险吗。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Moonglade sending support is assuring to hear, young one. The turmoil we are facing should be the co
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41339, '你说一个幽魂？还是白雄鹿的模样？若你亲眼所见属实，我们就不能再拖延了！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- A spectre, you say? In the form of a white stag? If what your eyes witnessed is true, then we cannot
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41340, '干得好，$C。见你如此迅速地完成任务，让我对接下来要托付你的事不再存疑。你或许不知，我的同胞与我皆是玛洛恩的后裔。正是他与月神伊露恩的结合，孕育了我们的父——塞纳留斯，而他又创造了我们。这事不仅关乎海加尔山或我族的安全，也关乎整个艾泽拉斯。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Well done, $C. Seeing you complete this task so quickly reassures me to not be doubtful of what I wi
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41341, '看到这些强大的饰品，会让你这样的凡人想起世间存在的种种力量。它们或许超出常人的理解，但也不要低估你自己在其中的作用。凡人一次又一次地证明，他们是改变艾泽拉斯命运的关键。你所做的每一件事都会带来后果，或早或晚。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Setting eyes upon these powerful trinkets reminds mortals like you of the forces present in this wor
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41347, '<这个瞎眼醉汉明显已经醉了。唯有打嗝和嗳气证明他还陪着你。他看上去已濒临死亡。>$B$B你想要啥？！没看见俺正忙着呢吗？！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <The blind drunkard is visibly intoxicated. Hiccups and burps are the only signs showing he is still
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41349, '<在泥土里翻找了片刻之后，你发现一具骸骨。从獠牙判断，那是兽人的遗骸。两样东西引起了你的注意：一条项链，外观与戈拉克在日志中描述的一模一样——这一定是他妻子梅拉尔。可惜，它不是蒂莉亚的项链。另一样是一把残破的剑，剑身已断，是年久还是战损，无从判断。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <After a few minutes of hard work rummaging through the dirt, you come across a skeleton. Judging fr
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41350, '这把剑深深烙在我的意识里，就算想忘也忘不掉。若你有时间，就让我讲讲我最出色的弟子的事吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- This sword is etched deep into my consciousness, something I cannot forget even if desired. Should y
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41356, '你又一次完成了任务。不论你还剩下哪些亲人，我希望他们想到你时会感到自豪。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You once more succeed to fulfill your task. For whatever kin you have left, I do hope they feel prid
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41357, '如同每一位伟大的奥术操控者，玛里苟斯渴求知识与试验。他将自己的法力注入诺森德的寒冰——或许那最接近某种元素的「原生」诞生地。也就是说，他那愚蠢的实验并没有好结果。如你所见，它并不像元素生物，而是一种冷酷无情的杀戮手段。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- As every great wielder of the Arcane, Malygos has the thirst of knowledge and experiment. He infused
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41359, '我……我恐怕得在某种程度上同意她的话。但怀着如此仇恨，还鼓吹灭绝整个种族？我的心沉了下去。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- I- I am afraid I have to agree with her words to a degree. But to harbor such hatred and encourage g
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41361, '山中之血！自从索瑞森的党羽控制了黑石山内外的所有采矿作业，想弄到这么一件宝贝就难上加难。而这一份似乎还是特别的品种……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Blood of the Mountain! Getting your hands on one of those beauties has been really difficult, ever s
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41365, '虽说生者如今被视为威胁，他的死也毫无道理可言。但这事必须有人去做……$B我会用余生哀悼你，威廉。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- While the living are now seen as a threat, his death was unjustifiable. It needed to be done...$BI w
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41370, '看到守护者的精华，我都在发抖——你能把它带到这里，足以证明你的意志之坚与体魄之强。如今所有部件都已齐备，修复权杖只需片刻。请退后一步，过程中恐怕会迸发不稳定的能量与狂暴的魔力。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- I am trembling at the sight of the guardians essence, that you were able to carry it here is a testa
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41371, '我从未见过这样的宝石。那青绿的色泽、它的结构与表面，在艾泽拉斯无可比拟。你为追寻真相所付出的努力，又一次令我惊叹。现在，让我们把这件事了结吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Ive never seen anything like this gemstone before. The teal color, its structure and surface are inc
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41377, '这么说，传说中的月神镰刀被找到了。梦风派你来找我算是明智，尽管他治愈海加尔的努力走错了方向。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- So, the fabled Scythe of Elune has been found. Dreamwind has been wise to send you to me, even if hi
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41382, '纯净的狼人之血，正如乌尔所描述。是的，这非常有用。它们曾是伊露恩最宠爱的孩子，能得到它们未被腐化的血……这将是仪式中的关键……不过现在听我说，我有很多事要讲。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Pure worgen blood, just like Ur described. Yes, this will be very useful. They were once the favouri
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41385, '狼人神父……一个浸透阴影的名字，却可能握有我们获救的钥匙。你挖出的这本日志虽然晦涩，却可能是揭开他那邪恶存在的真相的引线。让我们再次钻研乌尔的教诲，其中藏着破解这个谜团的智慧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Father Lycan... A name steeped in shadows, yet one that may hold the key to our salvation. This jour
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41387, '铁藤之根是一种凶悍的植物。被拔起时，它会缠住捕获者，试图将其拖倒在地，最终把人耗尽。而你并没有向这股自然之力低头。你心念清明，意志如铁。上一个通过这项考验的人是我的学徒萨克戈斯，那是许多年前的事了。或许我在你身上发现了非凡之人。接下来的试炼会证明我的判断是否正确。$B$B<马赛厄斯抽出匕首，快手一挥——快得你几乎看不清——把缠在你身上的藤蔓割了下来。>$B$B这东西不该浪费，用这藤根能泡出上好的茶。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The Ironvine Root is an aggressive plant. When uprooted it clings around its captor, trying to drag 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41391, '贾里德·沃斯？这名字让我想起好些事，真不愿如此。若这份文件属实，我们得立刻动身。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Jared Voss? I hate that this name rings several bells. If what is in this document is true, then we 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41639, '你可以从这些奖励中选择其一：侦测次级隐形药剂、次级隐形药水、抗魔药水') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Elixir of Detect Lesser Invisibility Lesser Invisibility Potion 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41916, '你可以从这些奖励中选择其一：清明指引腰带、粗野的披风、防御者轻锤、启发可汗顾问项圈') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Belt of Unclouded Guidance Brutalist Shroud Defenders Cudgel Cho
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41953, '你可以从这些奖励中选择其一：防御者之手镯、幻像之手镯、破坏者之手镯、神谕者之手镯') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Bracelet of the Defender Bracelet of the Visionary Bracelet of t
